/** Compute Entrypoint Contract
  *
  * guarantee RECOVERY_IMPLIES_OFF
  *   Every committed recovery state has commanded phase Off
  * @param current_phase post-state state variable
  * @param recovery_required post-state state variable
  */
pub fn compute_spec_RECOVERY_IMPLIES_OFF_guarantee(
  current_phase: Drone_Lifecycle_Governor::Lifecycle_Phase,
  recovery_required: bool) -> bool
{
  !recovery_required |
    (current_phase == Drone_Lifecycle_Governor::Lifecycle_Phase::Off)
}

/** CEP-T-Guar: Top-level guarantee contracts for lifecycle_governor's compute entrypoint
  *
  * @param current_phase post-state state variable
  * @param recovery_required post-state state variable
  */
pub fn compute_CEP_T_Guar(
  current_phase: Drone_Lifecycle_Governor::Lifecycle_Phase,
  recovery_required: bool) -> bool
{
  let r0: bool = compute_spec_RECOVERY_IMPLIES_OFF_guarantee(current_phase, recovery_required);

  return r0;
}

/** guarantee CASE_01_INVALID_INPUT
  *   Any invalid qualified input commands Off and enters recovery
  * @param current_phase post-state state variable
  * @param recovery_required post-state state variable
  * @param api_battery_evidence incoming data port
  * @param api_charge_sample incoming data port
  * @param api_qualified_request incoming data port
  * @param api_commanded_phase_report outgoing data port
  * @param api_decision_disposition outgoing data port
  * @param api_selected_phase outgoing data port
  */
pub fn compute_case_CASE_01_INVALID_INPUT(
  current_phase: Drone_Lifecycle_Governor::Lifecycle_Phase,
  recovery_required: bool,
  api_battery_evidence: Drone_Lifecycle_Governor::Battery_Evidence,
  api_charge_sample: Drone_Lifecycle_Governor::Charge_Connection_Sample,
  api_qualified_request: Drone_Lifecycle_Governor::Qualified_Request,
  api_commanded_phase_report: Drone_Lifecycle_Governor::Lifecycle_Phase,
  api_decision_disposition: Drone_Lifecycle_Governor::Decision_Disposition,
  api_selected_phase: Drone_Lifecycle_Governor::Lifecycle_Phase) -> bool
{
  implies!(
    invalid_input(api_qualified_request, api_battery_evidence, qualify_charge(api_charge_sample)),
    (current_phase == Drone_Lifecycle_Governor::Lifecycle_Phase::Off) &
      (recovery_required == true) &
      (api_selected_phase == Drone_Lifecycle_Governor::Lifecycle_Phase::Off) &
      (api_commanded_phase_report == Drone_Lifecycle_Governor::Lifecycle_Phase::Off) &
      (api_decision_disposition.input_fault_detected == true) &
      (api_decision_disposition.recovery_pending == true) &
      (api_decision_disposition.rejection_reason == Drone_Lifecycle_Governor::Rejection_Reason::No_Rejection))
}

